Voces.initScenarios=function(data){const $=id=>document.getElementById(id),base=Voces.year(data,2024).participation;$('scenarioBase').textContent=Voces.fmt(base)+' %';function draw(){const value=Number($('scenarioSlider').value);$('scenarioSlider').setAttribute('aria-valuetext',`${Voces.fmt(value)} por ciento, escenario hipotético`);$('scenarioIncrement').textContent=Voces.fmt(value)+' %';$('scenarioOutput').textContent=Voces.fmt(value)+' %';$('scenarioDifference').textContent=`${Voces.pp(Voces.delta(base,value))} respecto del valor observado; cambio relativo: ${Voces.fmt(Voces.relative(base,value))} %. No es una predicción.`;Voces.dots($('scenarioDots'),value,'Escenario hipotético');}$('scenarioSlider').oninput=draw;$('resetScenario').onclick=()=>{$('scenarioSlider').value=base;draw();};draw();};
